// swift-tools-version:5.9
import PackageDescription

// MuesliCore is Foundation plus the Rust core (MuesliFFI), so it builds on macOS only. muesli-mcp is the Rust binary in ../windows/crates/mcp.
// The menu bar app is macOS only.
var dependencies: [Package.Dependency] = []
var targets: [Target] = [
    // The shared Rust core (windows/crates/ffi). Both parts are generated by scripts/build-ffi.sh.
    .binaryTarget(name: "MuesliFFIBinary", path: "Frameworks/MuesliFFI.xcframework"),
    // The static library bundles whisper.cpp (through whisper-rs), which needs these system libraries.
    .target(name: "MuesliFFI", dependencies: ["MuesliFFIBinary"], path: "Sources/MuesliFFI", linkerSettings: [
        .linkedFramework("Accelerate"), .linkedFramework("Metal"), .linkedFramework("MetalKit"),
        .linkedFramework("Foundation"), .linkedLibrary("c++"),
    ]),
    .target(name: "MuesliCore", dependencies: ["MuesliFFI"], path: "Sources/MuesliCore"),
    .testTarget(name: "MuesliCoreTests", dependencies: ["MuesliCore"], path: "Tests/MuesliCoreTests"),
]

#if os(macOS)
targets.append(.executableTarget(
    name: "Muesli",
    dependencies: ["MuesliCore"],
    path: "Sources/Muesli"
))
#endif

let package = Package(
    name: "Muesli",
    platforms: [.macOS("14.4")],
    dependencies: dependencies,
    targets: targets
)
